"""Hip PD teaching overlay. Coordinates reviewed in native 640 x 670 source JPEGs.
Explicit per-frame positions, no propagation between planes or into T1/3D.
Source annotations/images remain byte-identical. All additions are approximate.
"""
import json, hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[1]; A=R/'app/src/main/assets'
D=json.loads((A/'hip-mri-data.json').read_text()); L=json.loads((A/'hip-mri-labels.json').read_text())
S={s['sourceSeries']:s for s in D['series'] if '_dp' in s['id']}
LIMIT='≈ и пунктир обозначают ориентировочную область, а не отдельно доказанные волокна или сегментацию. Разрешение обычной PD ограничивает разделение фасеток и мелких элементов губы. Не использовать эти ориентиры для заключения о целости. Независимая врачебная верификация не выполнена.'
E={'revision':'1.47','guideTitle':'ТБС · прикрепления сухожилий и суставная губа','filters':[
 {'id':14701,'name':'Сухожилия · прикрепления у вертелов','parent':None,'default':True,'icon':'wrist-mri-source/group-1258.png'},
 {'id':14702,'name':'Суставная губа · отделы и элементы','parent':None,'default':True,'icon':'wrist-mri-source/group-1259.png'}],
 'structureNotes':{},'displayNames':{},'shortNames':{},'catalogNames':{},'guideChapters':[],
 'sources':[
 {'title':'Pfirrmann et al. · MR/cadaveric anatomy of trochanteric tendon attachments (2001)','url':'https://pubmed.ncbi.nlm.nih.gov/11687692/'},
 {'title':'US and MRI of Pelvic Tendon Anatomy and Pathologic Conditions (2022)','url':'https://pubs.rsna.org/doi/10.1148/rg.220055'},
 {'title':'Hip Capsulolabral Complex: Anatomy, Disease, and MRI Features (2024)','url':'https://pubs.rsna.org/doi/10.1148/rg.230144'}],
 'limitations':[LIMIT,'Нет радиальных срезов и МР-артрографии: сектора губы обозначены по доступным плоскостям без точной часовой разметки. Нижний переход к поперечной связке отдельной точкой не выделен.'],
 'seriesSlices':{s['id']:{f['annotation']:{'points':[],'regions':[],'suppress':[]} for f in s['frames']} for s in S.values()}}
defs={}; records=[]
def define(id,name,note):
 defs[id]=name;E['catalogNames'][str(id)]=name;E['structureNotes'][str(id)]=note+' '+LIMIT
def points(id,se,rows,suppress=None):
 s=S[se]
 for n,x,y in rows:
  f=s['frames'][n-1];a=E['seriesSlices'][s['id']][f['annotation']]
  p={'id':147000000+len(records),'structure':id,'name':'≈ '+defs[id]+' · ориентировочно','shortName':'≈ '+defs[id],
     'filter':14701 if id<147201 else 14702,'x':x,'y':y,'category':'ligaments' if id<147201 else 'cartilage',
     'approximate':True,'provenance':'manual-pd-topography-1.47'}
  a['points'].append(p)
  if suppress and suppress not in a['suppress']:a['suppress'].append(suppress)
  records.append({'series':s['id'],'frame':n,'annotation':f['annotation'],'imageSha256':f['sha256'],**p})
for id,name,note in [
 (147101,'Средняя ягодичная · латеральное прикрепление','Сухожильное прикрепление к латеральной фасетке большого вертела. Отдельно от задневерхней фасетки; точка у сухожильно-костного перехода, не в костном мозге.'),
 (147102,'Средняя ягодичная · задневерхнее прикрепление','Ожидаемое прикрепление задней части сухожилия к задневерхней фасетке большого вертела. На этих PD граница фасеток условная; не переносить на заднюю фасетку, покрытую вертельной сумкой.'),
 (147103,'Малая ягодичная · переднее прикрепление','Сухожилие малой ягодичной прикрепляется к передней фасетке большого вертела, глубже средней ягодичной. Часть волокон связана с капсулой.'),
 (147104,'Подвздошно-поясничная · малый вертел','Дистальная область прикрепления к малому вертелу; подвздошные волокна могут продолжаться на прилежащую бедренную кость. На данном разрешении отдельные пучки подвздошной и большой поясничной не разделены.'),
 (147105,'Грушевидная · прикрепление к большому вертелу','Дистальное сухожилие к верхнему краю большого вертела. Не путать с задневерхним прикреплением средней ягодичной.'),
 (147106,'Запирательная внутренняя и близнецовые · прикрепление','Общая область прикрепления сухожильного комплекса внутренней запирательной и близнецовых к медиальной поверхности большого вертела. Три сухожилия здесь не обозначены как независимо прослеженные.'),
 (147107,'Запирательная наружная · вертельная ямка','Дистальное сухожилие наружной запирательной в вертельной ямке на медиальной поверхности большого вертела; глубже общего сухожилия внутренней запирательной/близнецовых.'),
 (147201,'Суставная губа · передний отдел','Передний край вертлужной впадины. Аксиальные срезы наиболее наглядно разделяют передний и задний отделы; на сагиттальных показан передневерхний переход.'),
 (147202,'Суставная губа · верхний отдел','Верхний сектор губы у крыши вертлужной впадины на фронтальных срезах. Передние/задние фронтальные кадры соответствуют переходам в передневерхний/задневерхний секторы.'),
 (147203,'Суставная губа · задний отдел','Задний край вертлужной впадины. На сагиттальных срезах — задневерхний переход. Не путать с задней капсулой и сухожилиями наружных ротаторов.'),
 (147204,'Суставная губа · основание','Ожидаемая периферическая зона фиксации губы к костному краю вертлужной впадины. Тонкая граница на обычной PD не всегда отделима; это топографический ориентир.'),
 (147205,'Суставная губа · свободный край','Внутренний заострённый край губы, обращённый к суставу и головке бедра. Отдельная точка не означает измерение толщины либо оценку разрыва.'),
 (147206,'Губа–хрящ · переходная зона','Ожидаемая хондролабральная переходная зона между суставным хрящом вертлужной впадины и основанием губы. Не обозначает подтверждённую щель, отслойку или разрыв.')]:define(id,name,note)
