report={'version':'1.47','sourceDataSha256':hashlib.sha256((A/'hip-mri-data.json').read_bytes()).hexdigest(),'sourceLabelsSha256':hashlib.sha256((A/'hip-mri-labels.json').read_bytes()).hexdigest(),'added':records,'coverage':coverage}
